from collections import deque

def min_steps(grid, c):
    R = len(grid)
    C = len(grid[0])
    target_r, target_c = R - 1, C - 1

    if grid[0][0] == -1 or grid[target_r][target_c] == -1:
        return -1

    def bfs(start_r, start_c):
        """Walking-only distances from the start cell; -1 means unreachable."""
        dist = [[-1] * C for _ in range(R)]
        dist[start_r][start_c] = 0
        queue = deque([(start_r, start_c)])

        while queue:
            r, col = queue.popleft()
            next_dist = dist[r][col] + 1

            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, col + dc
                if (
                    0 <= nr < R
                    and 0 <= nc < C
                    and grid[nr][nc] != -1
                    and dist[nr][nc] == -1
                ):
                    dist[nr][nc] = next_dist
                    queue.append((nr, nc))

        return dist

    from_start = bfs(0, 0)
    from_target = bfs(target_r, target_c)

    INF = 10**18

    # For each label store:
    # [best_start, best_start_id, second_start,
    #  best_target, best_target_id, second_target]
    label_stats = {}

    for r in range(R):
        for col in range(C):
            label = grid[r][col]
            if label == -1:
                continue

            stats = label_stats.get(label)
            if stats is None:
                stats = [INF, -1, INF, INF, -1, INF]
                label_stats[label] = stats

            cell_id = r * C + col

            d = from_start[r][col]
            if d != -1:
                if d < stats[0]:
                    stats[2] = stats[0]
                    stats[0] = d
                    stats[1] = cell_id
                elif d < stats[2]:
                    stats[2] = d

            d = from_target[r][col]
            if d != -1:
                if d < stats[3]:
                    stats[5] = stats[3]
                    stats[3] = d
                    stats[4] = cell_id
                elif d < stats[5]:
                    stats[5] = d

    # Option 1: never teleport.
    answer = from_start[target_r][target_c]
    if answer == -1:
        answer = INF

    # Option 2: walk to u, teleport u -> v, then walk from v to target.
    for s1, s_id, s2, t1, t_id, t2 in label_stats.values():
        if s1 == INF or t1 == INF:
            continue

        if s_id != t_id:
            candidate = s1 + t1 + c
        else:
            # The two best cells are the same cell, but teleporting requires
            # two distinct cells. Replace one of them by its second-best cell.
            walk_cost = min(s2 + t1, s1 + t2)
            if walk_cost >= INF:
                continue
            candidate = walk_cost + c

        answer = min(answer, candidate)

    return -1 if answer == INF else answer

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, [])
        for d in ds:
            graph.setdefault(d, [])
            graph[pkg].append(d)
    order = []
    visiting = set()  # nodes on the current DFS path (cycle detection)
    done = set()      # nodes fully emitted into `order`

    def visit(node):
        if node in done:
            return
        if node in visiting:
            raise ValueError("dependency cycle detected at " + node)
        visiting.add(node)
        for dep in sorted(set(graph[node])):  # set() collapses duplicate entries
            visit(dep)
        visiting.remove(node)   # leave the path: node is no longer "in progress"
        done.add(node)
        order.append(node)

    for node in sorted(graph):
        visit(node)
    return order

def apply_hunks(lines, hunks):
    ordered = sorted(hunks, key=lambda h: h[0])
    for i in range(1, len(ordered)):
        prev = ordered[i - 1]
        if ordered[i][0] == prev[0] or ordered[i][0] < prev[0] + prev[1]:
            raise ValueError("conflicting hunks")
    for start, delete, insert in ordered:
        if start < 0 or start + delete > len(lines):
            raise ValueError("hunk out of range")
    result = list(lines)
    for start, delete, insert in reversed(ordered):
        result[start:start + delete] = list(insert)
    return result

def purge_expired(sessions, now):
    purged = []
    for sid, expiry in list(sessions.items()):
        if expiry <= now:
            del sessions[sid]
            purged.append(sid)
    return purged

class RateLimiter:
    def __init__(self, max_calls, window_seconds):
        self.max_calls = max_calls
        self.window = window_seconds
        self.calls = []

    def allow(self, timestamp):
        self.calls = [t for t in self.calls if timestamp - t < self.window]
        if len(self.calls) < self.max_calls:
            self.calls.append(timestamp)
            return True
        return False

