T = TypeVar("T")


class CountingBag(Generic[T]):
    """A multiset that tracks item counts and current entry order."""

    def __init__(self) -> None:
        self._counts: dict[T, int] = {}
        self._entry_moments: dict[T, int] = {}
        self._next_entry_moment = 0
        self._size = 0

    def add(self, item: T) -> int:
        """Add one occurrence of item and return its new count."""
        new_count = self._counts.get(item, 0) + 1

        if new_count == 1:
            self._entry_moments[item] = self._next_entry_moment
            self._next_entry_moment += 1

        self._counts[item] = new_count
        self._size += 1
        return new_count

    def discard(self, item: T) -> bool:
        """Remove one occurrence of item, returning whether one was present."""
        current_count = self._counts.get(item, 0)
        if current_count == 0:
            return False

        if current_count == 1:
            del self._counts[item]
            del self._entry_moments[item]
        else:
            self._counts[item] = current_count - 1

        self._size -= 1
        return True

    def count(self, item: T) -> int:
        """Return the current count for item, or 0 if it is absent."""
        return self._counts.get(item, 0)

    def __len__(self) -> int:
        """Return the total number of occurrences in the bag."""
        return self._size

    def distinct(self) -> int:
        """Return the number of items with a positive count."""
        return len(self._counts)

    def most_common(self, k: int) -> list[tuple[T, int]]:
        """
        Return up to k items ordered by:
          1. count, descending
          2. current entry moment, ascending
        """
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []

        ordered = sorted(
            self._counts.items(),
            key=lambda entry: (-entry[1], self._entry_moments[entry[0]]),
        )
        return ordered[:k]

from collections import OrderedDict


class TTLCache:
    """Fixed-capacity LRU cache with per-entry TTLs on an explicit logical clock."""

    def __init__(self, capacity):
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 1:
            raise ValueError("capacity must be an integer >= 1")
        self._capacity = capacity
        # key -> (value, stored_time, ttl); iteration order is LRU -> MRU
        self._entries = OrderedDict()
        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0

    def _purge(self, now):
        """Remove every entry dead at `now`, counting each as an expiration."""
        dead = [
            key
            for key, (_, stored_at, ttl) in self._entries.items()
            if ttl is not None and now >= stored_at + ttl
        ]
        for key in dead:
            del self._entries[key]
            self._expirations += 1

    def put(self, key, value, now, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be a positive number or None")
        self._purge(now)
        if key in self._entries:
            # Update in place: refresh value, timestamp, ttl, and recency.
            self._entries[key] = (value, now, ttl)
            self._entries.move_to_end(key)
        else:
            if len(self._entries) >= self._capacity:
                self._entries.popitem(last=False)  # evict LRU
                self._evictions += 1
            self._entries[key] = (value, now, ttl)

    def get(self, key, now):
        self._purge(now)
        if key in self._entries:
            self._hits += 1
            self._entries.move_to_end(key)
            return self._entries[key][0]
        self._misses += 1
        return None

    def stats(self):
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
            "expirations": self._expirations,
        }

    def __len__(self):
        return len(self._entries)

class Leaderboard:
    """Tracks players' best (highest-ever) scores and ranks them.

    Ties in `top` are broken by who achieved their current best earlier
    in the overall sequence of improving submissions.
    """

    def __init__(self):
        self._best = {}         # player -> best score
        self._achieved_at = {}  # player -> sequence number of the submit that set the current best
        self._seq = 0           # monotonic counter over improving submissions

    def submit(self, player, score) -> bool:
        """Record an attempt. Return True iff it sets a new personal best.

        Non-improving submissions (including ties with the current best)
        change nothing, so tie-breaking order is preserved.
        """
        if player in self._best and score <= self._best[player]:
            return False
        self._best[player] = score
        self._achieved_at[player] = self._seq
        self._seq += 1
        return True

    def best(self, player) -> int:
        """The player's best score. Raises KeyError for unknown players."""
        return self._best[player]

    def rank(self, player) -> int:
        """Standard competition ranking: 1 + # players with a strictly greater best."""
        if player not in self._best:
            raise KeyError(player)
        b = self._best[player]
        return 1 + sum(1 for other in self._best.values() if other > b)

    def top(self, k) -> list:
        """Top-k players as (player, best) tuples.

        Ordered by best descending; ties by earliest achievement of that best.
        """
        if k < 0:
            raise ValueError("k must be non-negative")
        ordered = sorted(
            self._best.items(),
            key=lambda item: (-item[1], self._achieved_at[item[0]]),
        )
        return ordered[:k]

    def player_count(self) -> int:
        return len(self._best)

from __future__ import annotations

from typing import Dict, Generic, Hashable, List, TypeVar

K = TypeVar("K", bound=Hashable)
V = TypeVar("V")


class VersionedKV(Generic[K, V]):
    """Key-value store with commit snapshots, point-in-time reads, and rollback.

    Version numbers count committed snapshots: the first commit() returns 1,
    the next 2, and so on. Version 0 denotes the empty initial state and is
    valid only for rollback(). History is append-only: rollback never
    truncates it, so the next commit() always returns latest() + 1.
    """

    def __init__(self) -> None:
        self._working: Dict[K, V] = {}
        # _history[i] is the immutable snapshot for version (i + 1).
        self._history: List[Dict[K, V]] = []

    # ---------------- working-state operations ----------------

    def set(self, key: K, value: V) -> None:
        """Write to the working state."""
        self._working[key] = value

    def delete(self, key: K) -> None:
        """Remove key from the working state. Raises KeyError if absent."""
        del self._working[key]

    def get(self, key: K) -> V:
        """Read from the working state. Raises KeyError if absent."""
        return self._working[key]

    def has(self, key: K) -> bool:
        """Return True if key is present in the working state."""
        return key in self._working

    # ---------------- versioning ----------------

    def commit(self) -> int:
        """Snapshot the working state and return the new version number."""
        self._history.append(dict(self._working))  # copy: decouples snapshot from working state
        return len(self._history)

    def get_at(self, key: K, version: int) -> V:
        """Return key's value in snapshot `version`.

        Raises ValueError unless 1 <= version <= latest().
        Raises KeyError if that snapshot did not contain the key.
        """
        if not 1 <= version <= len(self._history):
            raise ValueError(
                f"invalid version {version!r}: must satisfy 1 <= version <= {len(self._history)}"
            )
        return self._history[version - 1][key]

    def rollback(self, version: int) -> None:
        """Replace the working state with a copy of snapshot `version` (0 = empty).

        Raises ValueError unless 0 <= version <= latest(). History is preserved.
        """
        if not 0 <= version <= len(self._history):
            raise ValueError(
                f"invalid version {version!r}: must satisfy 0 <= version <= {len(self._history)}"
            )
        # Copy so later working-state mutations can't corrupt the snapshot.
        self._working = {} if version == 0 else dict(self._history[version - 1])

    def latest(self) -> int:
        """Number of commits so far (0 if none)."""
        return len(self._history)

def kth_root_floor(n: int, k: int) -> int:
    """Return the largest integer r such that r**k <= n."""
    if n < 0:
        raise ValueError("n must be nonnegative")
    if k < 1:
        raise ValueError("k must be at least 1")

    if k == 1 or n < 2:
        return n

    # For n >= 2, 2**k > n whenever k >= n.bit_length().
    if k >= n.bit_length():
        return 1

    def power_is_at_most_n(x: int) -> bool:
        """Compute x**k, stopping as soon as it exceeds n."""
        result = 1
        base = x
        exp = k

        while exp:
            if exp & 1:
                result *= base
                if result > n:
                    return False

            exp >>= 1
            if exp:
                base *= base
                if base > n:
                    return False

        return True

    # Since n < 2**bit_length, this hi satisfies hi**k > n.
    lo = 1
    hi = 1 << ((n.bit_length() + k - 1) // k)

    # Invariant: lo**k <= n < hi**k.
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if power_is_at_most_n(mid):
            lo = mid
        else:
            hi = mid

    return lo

from collections import deque

def round_robin(iterables: list) -> "iterator":
    iterators = deque(iter(iterable) for iterable in iterables)

    while iterators:
        iterator = iterators.popleft()
        try:
            value = next(iterator)
        except StopIteration:
            # Exhausted iterators are removed from the rotation.
            continue

        yield value
        iterators.append(iterator)

from collections import deque

def count_stable_windows(readings: list[int], tol: int) -> int:
    max_q = deque()  # Indices of decreasing values
    min_q = deque()  # Indices of increasing values
    left = 0
    total = 0

    for right, value in enumerate(readings):
        while max_q and readings[max_q[-1]] <= value:
            max_q.pop()
        max_q.append(right)

        while min_q and readings[min_q[-1]] >= value:
            min_q.pop()
        min_q.append(right)

        # Move left until [left, right] satisfies the tolerance.
        while readings[max_q[0]] - readings[min_q[0]] > tol:
            left += 1
            if max_q[0] < left:
                max_q.popleft()
            if min_q[0] < left:
                min_q.popleft()

        # Every window starting at left, left+1, ..., right is valid.
        total += right - left + 1

    return total

def count_dominant_pairs(seq: list[int]) -> int:
    n = len(seq)
    if n < 2:
        return 0

    arr = list(seq)   # working copy; sorted in place during the recursion
    tmp = [0] * n     # scratch buffer for merging

    def sort_and_count(lo: int, hi: int) -> int:
        """Sort arr[lo:hi] ascending; return # of dominant pairs inside it."""
        if hi - lo < 2:
            return 0
        mid = (lo + hi) >> 1
        count = sort_and_count(lo, mid) + sort_and_count(mid, hi)

        # Count cross pairs: i in [lo, mid), j in [mid, hi), arr[i] > 3*arr[j].
        # Both halves are sorted, so j only advances across the whole sweep.
        j = mid
        for i in range(lo, mid):
            ai = arr[i]
            while j < hi and ai > 3 * arr[j]:
                j += 1
            count += j - mid

        # Merge the two sorted halves (skip if already ordered).
        if arr[mid - 1] > arr[mid]:
            tmp[lo:hi] = arr[lo:hi]
            p, q = lo, mid
            for k in range(lo, hi):
                if q >= hi or (p < mid and tmp[p] <= tmp[q]):
                    arr[k] = tmp[p]
                    p += 1
                else:
                    arr[k] = tmp[q]
                    q += 1
        return count

    return sort_and_count(0, n)

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")

    result = {}
    for i, row in enumerate(rows):
        # a. structure check
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(
                "row {0} must be a tuple of exactly 3 elements".format(i))
        category, amount, refunded = row

        # b. category check
        if not isinstance(category, str) or category == "":
            raise ValueError(
                "row {0} category must be a non-empty str".format(i))

        # c. amount type check (bool rejected before int/float)
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(
                "row {0} amount must be an int or float".format(i))

        # d. amount value check
        if amount < 0:
            raise ValueError(
                "row {0} amount must be >= 0".format(i))

        # e. refunded check
        if not isinstance(refunded, bool):
            raise TypeError(
                "row {0} refunded must be a bool".format(i))

        amount = float(amount)  # guarantees float outputs even for int inputs

        if category in result:
            summary = result[category]
            summary["count"] += 1
            summary["gross"] += amount
            if not refunded:
                summary["net"] += amount
            if amount > summary["largest"]:
                summary["largest"] = amount
        else:
            result[category] = {
                "count": 1,
                "gross": amount,
                "net": 0.0 if refunded else amount,
                "largest": amount,
            }

    return result

def clamp_values(values, low, high):
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    if (
        isinstance(low, bool)
        or isinstance(high, bool)
        or not isinstance(low, (int, float))
        or not isinstance(high, (int, float))
    ):
        raise TypeError("bounds must be numbers")
    if low > high:
        raise ValueError("low must not exceed high")

    result = []
    for i in range(len(values)):
        item = values[i]
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError(f"index {i} must be a number")
        if item < low:
            result.append(low)
        elif item > high:
            result.append(high)
        else:
            result.append(item)
    return result

def flatten_depth(nested, max_depth):
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")

    result = []
    # Explicit stack of (element, depth) pairs, processed LIFO.
    # Push children in reverse so left-to-right order is preserved on pop.
    stack = []
    for i in range(len(nested) - 1, -1, -1):
        stack.append((nested[i], 0))

    while stack:
        item, depth = stack.pop()
        if isinstance(item, list) and depth < max_depth:
            for i in range(len(item) - 1, -1, -1):
                stack.append((item[i], depth + 1))
        else:
            result.append(item)

    return result

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("expected str for duration text")
    if len(text) == 0 or text.isspace():
        raise ValueError("empty duration")

    total_seconds = 0
    seen_h = False
    seen_m = False
    seen_s = False
    i = 0
    n = len(text)

    while i < n:
        value = 0
        digits = 0

        while i < n:
            ch = text[i]
            if ch < "0" or ch > "9":
                break
            value = value * 10 + (ord(ch) - 48)
            i += 1
            digits += 1

        if digits == 0 or i == n:
            raise ValueError("malformed duration")

        unit = text[i]
        i += 1

        if unit == "h":
            if seen_h or seen_m or seen_s:
                raise ValueError("malformed duration")
            seen_h = True
            total_seconds += value * 3600
        elif unit == "m":
            if seen_m or seen_s:
                raise ValueError("malformed duration")
            seen_m = True
            total_seconds += value * 60
        elif unit == "s":
            if seen_s:
                raise ValueError("malformed duration")
            seen_s = True
            total_seconds += value
        else:
            raise ValueError("malformed duration")

    return total_seconds

def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    name_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_"
    out = []
    i = 0
    n = len(template)

    while i < n:
        ch = template[i]

        if ch == "{":
            if i + 1 < n and template[i + 1] == "{":
                out.append("{")
                i += 2
                continue

            p = i
            i += 1
            name_start = i

            while i < n and template[i] in name_chars:
                i += 1

            if i == n:
                raise ValueError("unclosed placeholder at position " + str(p))
            if template[i] != "}":
                raise ValueError("invalid placeholder at position " + str(p))
            if i == name_start:
                raise ValueError("empty placeholder at position " + str(p))

            name = template[name_start:i]
            out.append(str(context[name]))
            i += 1

        elif ch == "}":
            if i + 1 < n and template[i + 1] == "}":
                out.append("}")
                i += 2
            else:
                raise ValueError("stray '}' at position " + str(i))

        else:
            out.append(ch)
            i += 1

    return "".join(out)

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if tokens == []:
        raise ValueError("empty expression")

    stack = []
    operators = ("+", "-", "*", "/")

    for i, token in enumerate(tokens):
        if not isinstance(token, str):
            raise TypeError(f"token {i} must be a string")

        if token in operators:
            if len(stack) < 2:
                raise ValueError(f"stack underflow at token {i}")
            right = stack.pop()
            left = stack.pop()

            if token == "+":
                stack.append(left + right)
            elif token == "-":
                stack.append(left - right)
            elif token == "*":
                stack.append(left * right)
            else:
                if right == 0:
                    raise ZeroDivisionError(f"division by zero at token {i}")
                quotient = abs(left) // abs(right)
                if (left < 0) != (right < 0):
                    quotient = -quotient
                stack.append(quotient)
            continue

        start = 0
        if token and (token[0] == "+" or token[0] == "-"):
            start = 1
        if start == len(token):
            raise ValueError(f"unknown token at token {i}")

        for ch in token[start:]:
            if ch < "0" or ch > "9":
                raise ValueError(f"unknown token at token {i}")

        stack.append(int(token))

    if len(stack) > 1:
        raise ValueError("leftover operands")
    return stack[0]

def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")
    segments = path.split(".")
    _reject_empty_segments(segments)   # up front, before any navigation
    return _descend(data, segments)


def _reject_empty_segments(segments):
    if segments:
        if segments[0] == "":
            raise ValueError("empty segment in path")
        _reject_empty_segments(segments[1:])


def _is_index_literal(segment):
    # optional single leading "-", then one or more ASCII digits
    digits = segment[1:] if segment.startswith("-") else segment
    return digits != "" and digits.strip("0123456789") == ""


def _descend(node, segments):
    if not segments:
        return node
    segment = segments[0]
    rest = segments[1:]
    if isinstance(node, dict):
        if segment not in node:
            raise KeyError(segment)
        return _descend(node[segment], rest)
    if isinstance(node, list):
        if not _is_index_literal(segment):
            raise ValueError("invalid index: " + segment)
        index = int(segment)
        if index >= len(node) or index < -len(node):
            raise IndexError("index out of range: " + segment)
        return _descend(node[index], rest)
    raise TypeError("cannot descend into " + type(node).__name__)

def top_k_frequent(items, k):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be >= 0")

    counts = {}
    first_seen = []
    for value in items:
        if value in counts:
            counts[value] += 1
        else:
            counts[value] = 1
            first_seen.append(value)

    result = []
    pool = list(first_seen)
    while pool and len(result) < k:
        best_at = 0
        best_count = counts[pool[0]]
        i = 1
        while i < len(pool):
            current = counts[pool[i]]
            if current > best_count:
                best_count = current
                best_at = i
            i += 1
        chosen = pool.pop(best_at)
        result.append((chosen, counts[chosen]))
    return result
